INSERT INTO `event` VALUES (1,'Stephenson Open House ',8,'17:00:00','19:00:00','Stephenson Hall',0,0,0,0,'2022-09-12','celts@berea.edu','CELTS Admin',0,'Stephenson open house',NULL,9,0,NULL,NULL,0,0,NULL,0),(2,'All Volunteer Training',8,'15:00:00','16:00:00','Stephenson 214',1,0,0,1,'2022-09-15','celts@berea.edu','CELTS Admin',0,'Training for all CELTS programs',NULL,9,0,NULL,NULL,0,0,NULL,0),(7,'E KY Flood Relief Sept. 17',8,'07:45:00','17:30:00','Meet at lower Woods-Penn Circle (outside CPO)',0,1,1,0,'2022-09-17','celts@berea.edu','CELTS Admin',0,'Training required on 9/23/22 at 4 p.m. in LJAC. RSVP by Tuesday 9/20/22.\r\nA collaboration of CELTS, LJAC, CCC, and SGA, Berea College students will volunteer with Housing Development Alliance on Eastern Kentucky Flood Relief. https://hdahome.org/',NULL,9,0,NULL,NULL,0,0,NULL,0),(9,'E Ky Flood Relief Sept. 24, 2022',8,'06:45:00','20:00:00','Meet at lower Woods-Penn Circle (outside CPO)',0,1,1,0,'2022-09-24','celts@berea.edu','CELTS Admin',0,'THIS EVENT IS FULL. We can take up to 8 people on this trip; If more than 8 people sign up, you will be placed on a waiting list.\r\nTraining required on 9/23/22 at 4 p.m. in LJAC. RSVP by Tuesday 9/20/22.\r\nA collaboration of CELTS, LJAC, CCC, and SGA, Bere',NULL,9,0,NULL,NULL,0,0,NULL,0),(10,'E Ky Flood Relief Nov. 5, 2022',8,'06:45:00','20:00:00','Meet at lower Woods-Penn Circle (outside CPO)',0,1,1,0,'2022-11-05','celts@berea.edu','CELTS Admin',0,'*THIS EVENT IS FULL.* \r\nTraining required on 11/4/22 at 4 p.m. in LJAC. RSVP by Tuesday 11/1/22.\r\nA collaboration of CELTS, LJAC, CCC, and SGA, Berea College students will volunteer with Housing Development Alliance on Eastern Kentucky Flood Relief. https',NULL,9,0,NULL,NULL,0,0,NULL,0),(13,'All Volunteer Training',8,'16:00:00','17:00:00','Stephenson Hall',1,0,0,1,'2022-09-15','celts@berea.edu','CELTS Admin',0,'Training for all CELTS programs',NULL,9,0,NULL,NULL,0,0,NULL,0),(14,'E Ky Flood Relief Oct. 8, 2022',8,'06:45:00','20:00: